     */
    public int voidEvidence(long id, String actor, Instant at) {
        return jdbc.update("UPDATE incident_task_evidences SET status = 'VOIDED',"
                        + " voided_by = ?, voided_at = ?, updated_at = ?"
                        + " WHERE id = ? AND status IN ('PENDING','CONFIRMED')",
                actor, Timestamp.from(at), Timestamp.from(at), id);
    }

    /**
     * 任务完成时冻结全部证据：写入统一的冻结 UTC 时刻，此后内容与确认人不可改。
     */
    public void freezeByTask(long taskId, Instant at) {
        jdbc.update("UPDATE incident_task_evidences SET frozen_at = ?, updated_at = ?"
                        + " WHERE task_id = ? AND frozen_at IS NULL",
                Timestamp.from(at), Timestamp.from(at), taskId);
    }

