                        + " WHERE task_id = ? ORDER BY id",
                (rs, n) -> rs.getString("category"), taskId);
    }

    /**
     * 整体替换任务的必需证据类别（先删后插，同事务提交）。
     */
    public void replaceRequirements(long taskId, List<String> categories, Instant at) {
        jdbc.update("DELETE FROM incident_task_required_categories WHERE task_id = ?", taskId);
        for (String category : categories) {
            jdbc.update("INSERT INTO incident_task_required_categories (task_id, category,"
                    + " created_at) VALUES (?,?,?)", taskId, category, Timestamp.from(at));
        }
    }

    /**
     * 查询任务当前已确认（CONFIRMED 且未作废）证据覆盖的类别集合，用于完成门禁判定。
     */
    public Set<String> listConfirmedCategories(long taskId) {
        return new HashSet<>(jdbc.query("SELECT DISTINCT category FROM incident_task_evidences"
                        + " WHERE task_id = ? AND status = 'CONFIRMED'",
                (rs, n) -> rs.getString("category"), taskId));
    }
}
